from fractions import Fraction
from itertools import combinations, permutations

def calculate_R_S4(S4):
    """
    Calculates R(S4), the minimum required T for a set of 4 numbers S4.
    R(S4) = min_{assignments} |e/h - g/f|
    """
    S4_list = list(S4)
    n = len(S4_list)
    if n != 4:
        raise ValueError("Input must have exactly 4 elements.")

    min_diff = float('inf')

    # 1. Iterate over all 3 ways to partition S4 into two pairs P1 and P2
    # We choose 2 elements for P1, and the remaining 2 form P2.
    for p1_indices in combinations(range(4), 2):
        p1 = {S4_list[i] for i in p1_indices}
        p2 = {S4_list[i] for i in range(4)} - p1

        p1_list = list(p1)
        p2_list = list(p2)

        # Possible ratios for P1: {a/b, b/a}
        ratios_p1 = [Fraction(p1_list[0], p1_list[1]), Fraction(p1_list[1], p1_list[0])]

        # Possible ratios for P2: {c/d, d/c}
        ratios_p2 = [Fraction(p2_list[0], p2_list[1]), Fraction(p2_list[1], p2_list[0])]

        # 2. Find the minimum difference between a ratio from P1 and a ratio from P2
        for r1 in ratios_p1:
            for r2 in ratios_p2:
                diff = abs(r1 - r2)
                if diff < min_diff:
                    min_diff = diff

    return min_diff

